fs.mkdirSync(path.dirname(DATABASE_PATH), { recursive: true });
const db = new DatabaseSync(DATABASE_PATH);
db.exec('PRAGMA journal_mode = WAL;');
db.exec('PRAGMA foreign_keys = ON;');
db.exec(`
  CREATE TABLE IF NOT EXISTS orders (
    id TEXT PRIMARY KEY,
    order_type TEXT NOT NULL DEFAULT 'purchase',
    stripe_session_id TEXT UNIQUE,
    customer_name TEXT,
    email TEXT,
    phone TEXT,
    amount_total INTEGER NOT NULL DEFAULT 0,
    currency TEXT NOT NULL DEFAULT 'eur',
    payment_status TEXT NOT NULL DEFAULT 'pending',
    fulfillment_status TEXT NOT NULL DEFAULT 'new',
    shipping_json TEXT,
    items_json TEXT NOT NULL,
    tracking_number TEXT,
    tracking_url TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS contact_messages (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL,
    message TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'new',
    created_at TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS newsletter (
    email TEXT PRIMARY KEY,
    created_at TEXT NOT NULL
  );
`);

function ensureColumn(table, column, sqlType) {
  const cols = db.prepare(`PRAGMA table_info(${table})`).all().map(row => row.name);
  if (!cols.includes(column)) db.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${sqlType}`);
}
ensureColumn('orders', 'tracking_number', 'TEXT');
ensureColumn('orders', 'tracking_url', 'TEXT');

const stmts = {
  insertOrder: db.prepare(`
    INSERT INTO orders (
      id, order_type, stripe_session_id, customer_name, email, phone,
      amount_total, currency, payment_status, fulfillment_status,
      shipping_json, items_json, tracking_number, tracking_url, created_at, updated_at
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `),
  updateOrderSession: db.prepare(`UPDATE orders SET stripe_session_id = ?, updated_at = ? WHERE id = ?`),
  updateOrderPayment: db.prepare(`
    UPDATE orders SET amount_total = ?, currency = ?, payment_status = ?, email = COALESCE(email, ?), updated_at = ? WHERE id = ?
  `),
  updateOrderPaymentBySession: db.prepare(`UPDATE orders SET payment_status = ?, updated_at = ? WHERE stripe_session_id = ?`),
  listOrders: db.prepare(`SELECT * FROM orders ORDER BY datetime(created_at) DESC`),
  getOrderById: db.prepare(`SELECT * FROM orders WHERE id = ?`),
  getOrderBySession: db.prepare(`SELECT * FROM orders WHERE stripe_session_id = ?`),
  updateFulfillment: db.prepare(`UPDATE orders SET fulfillment_status = ?, tracking_number = ?, tracking_url = ?, updated_at = ? WHERE id = ?`),
  insertContact: db.prepare(`INSERT INTO contact_messages (id, name, email, message, status, created_at) VALUES (?, ?, ?, ?, 'new', ?)`),
  listContacts: db.prepare(`SELECT * FROM contact_messages ORDER BY datetime(created_at) DESC LIMIT 100`),
  getContact: db.prepare(`SELECT * FROM contact_messages WHERE id = ?`),
  updateContactStatus: db.prepare(`UPDATE contact_messages SET status = ? WHERE id = ?`),
  insertNewsletter: db.prepare(`INSERT OR IGNORE INTO newsletter (email, created_at) VALUES (?, ?)`),
  countNewsletter: db.prepare(`SELECT COUNT(*) AS count FROM newsletter`),
  deleteNewsletter: db.prepare(`DELETE FROM newsletter WHERE email = ?`),
};

function nowIso() { return new Date().toISOString(); }
function randomId(prefix) { return `${prefix}-${crypto.randomBytes(6).toString('hex').toUpperCase()}`; }
function makeOrderId() {
  const date = new Date();
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, '0');
  const d = String(date.getUTCDate()).padStart(2, '0');
  return `PS-${y}${m}${d}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
}
function clean(value, max = 200) { return String(value ?? '').trim().slice(0, max); }
function validEmail(value) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value); }

function normalizeCart(rawCart) {
  if (!Array.isArray(rawCart)) throw new Error('Panier invalide.');
  const grouped = new Map();
  for (const rawItem of rawCart) {
    const id = String(rawItem?.id || '').toLowerCase();
    const product = CATALOG[id];
    const qty = Number.parseInt(rawItem?.qty, 10);
    if (!product || !Number.isInteger(qty) || qty < 1 || qty > 10) continue;
    grouped.set(id, Math.min(10, (grouped.get(id) || 0) + qty));
  }
  const items = [...grouped.entries()].map(([id, qty]) => ({ ...CATALOG[id], qty }));
  if (!items.length) throw new Error('Votre panier est vide.');
  return items;
}

function normalizeCustomer(raw) {
  const customer = {
    name: clean(raw?.name, 100),
    email: clean(raw?.email, 160).toLowerCase(),
    phone: clean(raw?.phone, 30),
    line1: clean(raw?.line1, 120),
    line2: clean(raw?.line2, 120),
    postalCode: clean(raw?.postalCode, 12),
    city: clean(raw?.city, 80),
    country: 'FR',
  };
  if (customer.name.length < 2) throw new Error('Indiquez votre nom et prénom.');
  if (!validEmail(customer.email)) throw new Error('Adresse e-mail invalide.');
  if (customer.line1.length < 3) throw new Error('Adresse de livraison incomplète.');
  if (customer.postalCode.length < 3) throw new Error('Code postal invalide.');
  if (customer.city.length < 2) throw new Error('Ville invalide.');
  return customer;
}

function cartSubtotal(items) { return items.reduce((sum, item) => sum + item.unitAmount * item.qty, 0); }
function shippingAmountFor(subtotal) { return subtotal >= 4900 ? 0 : 490; }
function safeJson(value, fallback) { try { return value ? JSON.parse(value) : fallback; } catch { return fallback; } }

function publicOrder(row) {
  return {
    id: row.id,
    orderType: row.order_type,
    customerName: row.customer_name,
    email: row.email,
    phone: row.phone,
    amountTotal: row.amount_total,
    currency: row.currency,
    paymentStatus: row.payment_status,
    fulfillmentStatus: row.fulfillment_status,
    shipping: safeJson(row.shipping_json, null),
    items: safeJson(row.items_json, []),
    trackingNumber: row.tracking_number,
    trackingUrl: row.tracking_url,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function safePublicTrackingOrder(row) {
  return {
    id: row.id,
    amountTotal: row.amount_total,
    currency: row.currency,
    paymentStatus: row.payment_status,
    fulfillmentStatus: row.fulfillment_status,
    items: safeJson(row.items_json, []).map(({ id, name, unitAmount, qty }) => ({ id, name, unitAmount, qty })),
    trackingNumber: row.tracking_number,
    trackingUrl: row.tracking_url,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function issueAdminCookie(res) {
  if (!ADMIN_TOKEN_SECRET) throw new Error('ADMIN_TOKEN_SECRET manquant.');
  const expires = Date.now() + 12 * 60 * 60 * 1000;
  const payload = String(expires);
  const sig = crypto.createHmac('sha256', ADMIN_TOKEN_SECRET).update(payload).digest('hex');
  const cookie = [`ps_admin=${payload}.${sig}`, 'HttpOnly', 'Path=/', 'SameSite=Strict', `Max-Age=${12 * 60 * 60}`, IS_PRODUCTION ? 'Secure' : ''].filter(Boolean).join('; ');
  res.setHeader('Set-Cookie', cookie);
}
function clearAdminCookie(res) { res.setHeader('Set-Cookie', `ps_admin=; HttpOnly; Path=/; SameSite=Strict; Max-Age=0${IS_PRODUCTION ? '; Secure' : ''}`); }
function parseCookies(req) {
  return Object.fromEntries((req.headers.cookie || '').split(';').map(p => p.trim()).filter(Boolean).map(part => {
    const idx = part.indexOf('=');
    return idx === -1 ? [part, ''] : [part.slice(0, idx), decodeURIComponent(part.slice(idx + 1))];
  }));
}
function verifyAdmin(req) {
  if (!ADMIN_TOKEN_SECRET) return false;
  const token = parseCookies(req).ps_admin;
  if (!token) return false;
  const [payload, signature] = token.split('.');
  if (!payload || !signature || Number(payload) < Date.now()) return false;
  const expected = crypto.createHmac('sha256', ADMIN_TOKEN_SECRET).update(payload).digest('hex');
  const a = Buffer.from(signature); const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
function requireAdmin(req, res, next) {
  if (!verifyAdmin(req)) return res.status(401).json({ error: 'Connexion administrateur requise.' });
  next();
}

