// Stripe exige le corps brut pour vérifier la signature.
app.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  if (!stripe || !process.env.STRIPE_WEBHOOK_SECRET || process.env.STRIPE_WEBHOOK_SECRET.includes('remplace_moi')) {
    return res.status(503).send('Webhook Stripe non configuré.');
  }
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, req.headers['stripe-signature'], process.env.STRIPE_WEBHOOK_SECRET);
  } catch (error) {
    return res.status(400).send(`Webhook Error: ${error.message}`);
  }
  try {
    if (event.type === 'checkout.session.completed') handleCheckoutCompleted(event.data.object);
    if (event.type === 'checkout.session.async_payment_succeeded') stmts.updateOrderPaymentBySession.run('paid', nowIso(), event.data.object.id);
    if (event.type === 'checkout.session.async_payment_failed') stmts.updateOrderPaymentBySession.run('failed', nowIso(), event.data.object.id);
  } catch (error) {
    console.error('Erreur webhook:', error);
    return res.status(500).send('Erreur de traitement du webhook.');
  }
  res.json({ received: true });
});

