app.post('/api/create-checkout-session', async (req, res) => {
  if (!stripe) return res.status(503).json({ error: 'Stripe n’est pas encore configuré. Ajoutez vos clés dans le fichier .env.' });
  let items, customer;
  try {
    items = normalizeCart(req.body?.cart);
    customer = normalizeCustomer(req.body?.customer);
  } catch (error) {
    return res.status(400).json({ error: error.message });
  }
  if (req.body?.acceptedTerms !== true) return res.status(400).json({ error: 'Vous devez accepter les CGV pour commander.' });

  const subtotal = cartSubtotal(items);
  const shippingAmount = shippingAmountFor(subtotal);
  const orderId = makeOrderId();
  const createdAt = nowIso();
  const serializedItems = JSON.stringify(items.map(item => ({ id: item.id, name: item.name, unitAmount: item.unitAmount, qty: item.qty })));
  const shipping = { name: customer.name, address: { line1: customer.line1, line2: customer.line2 || null, postal_code: customer.postalCode, city: customer.city, country: customer.country } };

  stmts.insertOrder.run(
    orderId, 'purchase', null, customer.name, customer.email, customer.phone || null,
    subtotal + shippingAmount, 'eur', 'pending', 'new', JSON.stringify(shipping), serializedItems,
    null, null, createdAt, createdAt
  );

  const lineItems = items.map(item => ({
    quantity: item.qty,
    price_data: { currency: 'eur', unit_amount: item.unitAmount, product_data: { name: item.name, description: item.description, metadata: { product_id: item.id } } },
  }));
  if (shippingAmount > 0) {
    lineItems.push({ quantity: 1, price_data: { currency: 'eur', unit_amount: shippingAmount, product_data: { name: 'Livraison standard France' } } });
  }

  try {
    const session = await stripe.checkout.sessions.create({
      mode: 'payment',
      locale: 'fr',
      customer_email: customer.email,
      client_reference_id: orderId,
      metadata: { order_id: orderId },
      line_items: lineItems,
      allow_promotion_codes: true,
      billing_address_collection: 'auto',
      success_url: `${BASE_URL}/success.html?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${BASE_URL}/checkout.html?checkout=cancelled`,
      payment_intent_data: { metadata: { order_id: orderId } },
    });
    stmts.updateOrderSession.run(session.id, nowIso(), orderId);
    res.json({ url: session.url, orderId });
  } catch (error) {
    console.error('Création Checkout échouée:', error);
    res.status(500).json({ error: 'Impossible d’ouvrir le paiement pour le moment.' });
  }
});

app.get('/api/checkout-session', async (req, res) => {
  if (!stripe) return res.status(503).json({ error: 'Stripe non configuré.' });
  const sessionId = String(req.query.session_id || '');
  if (!sessionId.startsWith('cs_')) return res.status(400).json({ error: 'Session invalide.' });
  try {
    const session = await stripe.checkout.sessions.retrieve(sessionId);
    const orderId = session.metadata?.order_id || session.client_reference_id;
    const row = orderId ? stmts.getOrderById.get(orderId) : stmts.getOrderBySession.get(sessionId);
    if (!row) return res.status(404).json({ error: 'Commande introuvable.' });
    res.json({ order: publicOrder(row), stripePaymentStatus: session.payment_status, customerEmail: session.customer_details?.email || row.email });
  } catch (error) {
    res.status(400).json({ error: 'Impossible de lire cette commande.' });
  }
});

app.get('/api/order-status', (req, res) => {
  const id = clean(req.query.id, 60).toUpperCase();
  const email = clean(req.query.email, 160).toLowerCase();
  if (!id || !validEmail(email)) return res.status(400).json({ error: 'Indiquez le numéro de commande et l’e-mail utilisés lors de l’achat.' });
  const row = stmts.getOrderById.get(id);
  if (!row || String(row.email || '').toLowerCase() !== email) return res.status(404).json({ error: 'Aucune commande ne correspond à ces informations.' });
  res.json({ order: safePublicTrackingOrder(row) });
});

