const loginAttempts = new Map();
app.post('/api/admin/login', (req, res) => {
  const ip = req.ip || 'unknown';
  const current = loginAttempts.get(ip) || { count: 0, resetAt: Date.now() + 10 * 60 * 1000 };
  if (Date.now() > current.resetAt) { current.count = 0; current.resetAt = Date.now() + 10 * 60 * 1000; }
  if (current.count >= 8) return res.status(429).json({ error: 'Trop de tentatives. Réessayez plus tard.' });
  if (!ADMIN_PASSWORD || !ADMIN_TOKEN_SECRET) return res.status(503).json({ error: 'L’espace admin n’est pas encore configuré dans .env.' });
  const supplied = String(req.body?.password || '');
  const a = Buffer.from(supplied); const b = Buffer.from(ADMIN_PASSWORD);
  const ok = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!ok) { current.count += 1; loginAttempts.set(ip, current); return res.status(401).json({ error: 'Mot de passe incorrect.' }); }
  loginAttempts.delete(ip); issueAdminCookie(res); res.json({ ok: true });
});
app.post('/api/admin/logout', (req, res) => { clearAdminCookie(res); res.json({ ok: true }); });
app.get('/api/admin/session', (req, res) => { res.json({ authenticated: verifyAdmin(req) }); });
app.get('/api/admin/orders', requireAdmin, (req, res) => { res.json({ orders: stmts.listOrders.all().map(publicOrder), newsletterCount: stmts.countNewsletter.get().count }); });
app.patch('/api/admin/orders/:id', requireAdmin, (req, res) => {
  const allowed = new Set(['new', 'preparing', 'shipped', 'delivered', 'cancelled']);
  const fulfillmentStatus = clean(req.body?.fulfillmentStatus, 30);
  if (!allowed.has(fulfillmentStatus)) return res.status(400).json({ error: 'Statut invalide.' });
  const order = stmts.getOrderById.get(req.params.id);
  if (!order) return res.status(404).json({ error: 'Commande introuvable.' });
  let trackingNumber = clean(req.body?.trackingNumber, 100) || null;
  let trackingUrl = clean(req.body?.trackingUrl, 500) || null;
  if (trackingUrl && !/^https:\/\//i.test(trackingUrl)) return res.status(400).json({ error: 'Le lien de suivi doit commencer par https://.' });
  stmts.updateFulfillment.run(fulfillmentStatus, trackingNumber, trackingUrl, nowIso(), req.params.id);
  res.json({ order: publicOrder(stmts.getOrderById.get(req.params.id)) });
});
app.get('/api/admin/messages', requireAdmin, (req, res) => { res.json({ messages: stmts.listContacts.all() }); });
app.patch('/api/admin/messages/:id', requireAdmin, (req, res) => {
  const status = clean(req.body?.status, 20);
  if (!['new', 'read'].includes(status)) return res.status(400).json({ error: 'Statut invalide.' });
  if (!stmts.getContact.get(req.params.id)) return res.status(404).json({ error: 'Message introuvable.' });
  stmts.updateContactStatus.run(status, req.params.id); res.json({ ok: true });
});

app.use((req, res, next) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') return next();
  let filePath = req.path === '/' ? '/index.html' : req.path;
  if (!filePath.includes('.') && EMBEDDED_FILES[`${filePath}.html`]) filePath = `${filePath}.html`;
  const file = EMBEDDED_FILES[filePath];
  if (!file) return next();
  res.setHeader('Content-Type', file.mime);
  if (filePath.startsWith('/assets/')) res.setHeader('Cache-Control', 'public, max-age=86400');
  const body = Buffer.from(file.data, 'base64');
  res.setHeader('Content-Length', String(body.length));
  if (req.method === 'HEAD') return res.end();
  res.end(body);
});
app.use((error, req, res, next) => { console.error(error); res.status(500).json({ error: 'Erreur serveur.' }); });

function handleCheckoutCompleted(session) {
  const orderId = session.metadata?.order_id || session.client_reference_id;
  if (!orderId) return;
  const row = stmts.getOrderById.get(orderId);
  if (!row) return;
  const paymentStatus = session.payment_status === 'paid' ? 'paid' : 'pending';
  stmts.updateOrderPayment.run(session.amount_total || row.amount_total, session.currency || row.currency, paymentStatus, session.customer_details?.email || null, nowIso(), orderId);
}

